from __future__ import annotations

import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def build_manifest(evidence_root: Path) -> dict:
    collected_at = utc_now()
    records = []
    for path in sorted(p for p in evidence_root.rglob("*") if p.is_file()):
        records.append({
            "relativePath": path.relative_to(evidence_root).as_posix(),
            "size": path.stat().st_size,
            "sha256": sha256_file(path),
            "collectedAt": collected_at,
        })
    return {
        "schemaVersion": 1,
        "algorithm": "SHA-256",
        "evidenceRoot": str(evidence_root.resolve()),
        "createdAt": collected_at,
        "records": records,
    }


def verify_manifest(manifest_path: Path, evidence_root: Path) -> list[dict]:
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    results = []
    for record in manifest["records"]:
        path = evidence_root / record["relativePath"]
        result = {"path": record["relativePath"], "status": "MISSING"}
        if path.is_file():
            actual_hash = sha256_file(path)
            result["status"] = "MATCH" if actual_hash == record["sha256"] else "MISMATCH"
            result["expectedSha256"] = record["sha256"]
            result["actualSha256"] = actual_hash
        results.append(result)
    return results


def append_chain_event(path: Path, evidence_id: str, from_actor: str, to_actor: str, location: str) -> None:
    event = {
        "timestamp": utc_now(),
        "evidenceId": evidence_id,
        "from": from_actor,
        "to": to_actor,
        "location": location,
    }
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(event, sort_keys=True) + "\n")
